```

```kotlin
// Illustrative: source registry with isolated ClassLoader
@Singleton
class SourceManager @Inject constructor(
    @ApplicationContext private val context: Context
) {
    private val internalSources = mutableMapOf<String, ShinKuSource>()
    private val externalSources = mutableMapOf<String, ShinKuSource>()

    fun registerInternal(source: ShinKuSource) {
        internalSources[source.id] = source
    }

    fun loadExternal(apkPath: String) {
        val classLoader = PathClassLoader(apkPath, context.classLoader.parent)
        // Signature verification omitted for brevity; mandatory in production
        val entryClass = classLoader.loadClass("shinku.source.Entry")
        val factory = entryClass.getDeclaredMethod("create").invoke(null) as SourceFactory
        factory.create().forEach { source ->
            externalSources[source.id] = source
        }
    }

    fun getSource(id: String): ShinKuSource? {
        return internalSources[id] ?: externalSources[id]
    }

    fun getAllSources(): List<ShinKuSource> {
        return (internalSources.values + externalSources.values).toList()
    }
}
