```kotlin
// Illustrative: multi-source search aggregation
class CatalogRepository @Inject constructor(
    private val sourceManager: SourceManager
) {
    fun search(query: String): Flow<SearchResult> = flow {
        val sources = sourceManager.getAllSources().filter { it.supportsSearch }

        sources.map { source ->
            async {
                runCatching {
                    source.fetchSearchResults(query, 1)
                }.getOrElse { emptyList() }
            }
        }.awaitAll().flatten().forEach { manga ->
            emit(SearchResult(manga, sourceManager.getSource(manga.sourceId)?.name ?: "Unknown"))
        }
    }.flowOn(Dispatchers.IO)
}
