// Illustrative: webtoon image with height placeholder
@Composable
fun WebtoonImage(url: String, onVisible: () -> Unit) {
    var imageHeight by remember { mutableIntStateOf(0) }
    val screenWidth = LocalConfiguration.current.screenWidthDp.dp

    // Estimated height before load (typical webtoon 1:3 ratio)
    val estimatedHeight = if (imageHeight > 0) imageHeight.dp else screenWidth * 3

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(estimatedHeight)
            .onGloballyPositioned { onVisible() }
    ) {
        AsyncImage(
            model = ImageRequest.Builder(LocalContext.current)
                .data(url)
                .crossfade(true)
                .listener { _, result ->
                    imageHeight = (result.drawable.intrinsicHeight * screenWidth.value / result.drawable.intrinsicWidth).toInt()
                }
                .build(),
            contentDescription = null,
            contentScale = ContentScale.FillWidth,
            modifier = Modifier.fillMaxWidth()
        )
    }
}
```

```kotlin
// Illustrative: adjacent image preloader
class WebtoonPreloader(
    private val preloadDistance: Int = 3
) {
    private val loadedPages = mutableSetOf<Int>()

    fun onPageVisible(currentIndex: Int, totalPages: Int, loadPage: (Int) -> Unit) {
        val range = (currentIndex - 1)..(currentIndex + preloadDistance)
        range.filter { it in 0 until totalPages && it !in loadedPages }
            .forEach { index ->
                loadedPages.add(index)
                loadPage(index)
            }
    }
}
```

### Step 4: Bulk source migration

Confidence: C (pattern observed in Tadami-Aniyomi-fork; illustrative file names)

**Scope.** A tool that automatically detects when a source stops working (persistent HTTP errors, empty responses, or domain changes) and offers to migrate affected titles to other installed, active sources. Matching uses fuzzy comparison of normalized titles, and migration preserves reading progress, categories, and private notes.

**Note.** Bulk migration involves large-scale writes to the local database. An atomic transaction or rollback mechanism is needed to avoid leaving the library in an intermediate state if migration is interrupted. Fuzzy matching can produce false positives; the user must confirm each match before it's applied.

| Type | Illustrative name | Responsibility |
|---|---|---|
| New | `MigrationManager.kt` | Orchestrates the full flow: detection, matching, confirmation, execution. |
| New | `MigrationService.kt` | Background service that runs the match search. |
| New | `TitleMatcher.kt` | Title normalization and fuzzy-comparison algorithm. |
| New | `MigrationRepository.kt` | Persists migration results in Room. |
| Modify | `LibraryScreen.kt` | Adds a "Migrate sources" entry and progress dialog. |
| Modify | `SourceManager.kt` | Exposes the list of active sources for alternative lookup. |

**Architectural decisions**

- *Dead-source detection*: a periodic `WorkManager` job checks each active in-library source's health via a lightweight request (e.g. `fetchPopularManga(1)`). If a source fails N consecutive attempts (configurable, default 3), it's marked `DEGRADED` and the user is notified. Migration is never automatic — only suggested.
- *Fuzzy matching with normalization*: `TitleMatcher` normalizes titles by (a) lowercasing, (b) stripping special characters and extra whitespace, (c) transliterating non-ASCII characters where applicable, (d) removing common stopwords ("the", "vol.", "chapter"). Comparison uses Levenshtein distance with a similarity threshold (default 85%). If multiple matches exceed the threshold, all are presented to the user.
- *Metadata preservation*: migrating a title from source A to source B transfers reading progress (last chapter read), status (`reading`, `completed`, etc.), categories, private note, and library-added date. Reading history is kept as a reference, though specific chapter IDs from the old source aren't transferable (chapter IDs differ between sources).
- *Atomic transaction*: migrating a single title runs inside a Room transaction. If the transaction fails (e.g. a unique-key constraint), the original title is left unmodified. Bulk migration processes titles one by one, reporting individual successes and failures.

```kotlin
// Illustrative: title normalization and fuzzy comparison
class TitleMatcher @Inject constructor() {

    fun findMatches(
        title: String,
        candidates: List<MangaDto>,
        threshold: Double = 0.85
    ): List<MatchResult> {
        val normalizedQuery = normalize(title)

        return candidates.mapNotNull { candidate ->
            val normalizedCandidate = normalize(candidate.title)
            val similarity = calculateLevenshteinSimilarity(normalizedQuery, normalizedCandidate)
            if (similarity >= threshold) {
                MatchResult(candidate, similarity)
            } else null
        }.sortedByDescending { it.similarity }
    }

    private fun normalize(input: String): String {
        return input.lowercase()
            .replace(Regex("[^a-z0-9\\s]"), "")
            .replace(Regex("\\s+"), " ")
            .trim()
            .removeCommonWords()
    }

    private fun String.removeCommonWords(): String {
        val common = setOf("the", "a", "an", "vol", "volume", "chapter", "ch")
        return split(" ").filter { it !in common }.joinToString(" ")
    }

    private fun calculateLevenshteinSimilarity(a: String, b: String): Double {
        val maxLength = maxOf(a.length, b.length)
        if (maxLength == 0) return 1.0
        val distance = levenshtein(a, b)
        return (maxLength - distance).toDouble() / maxLength
    }

    private fun levenshtein(a: String, b: String): Int {
        val dp = Array(a.length + 1) { IntArray(b.length + 1) }
        for (i in a.indices) dp[i][0] = i
        for (j in b.indices) dp[0][j] = j
        for (i in 1..a.length) {
            for (j in 1..b.length) {
                dp[i][j] = if (a[i - 1] == b[j - 1]) {
                    dp[i - 1][j - 1]
                } else {
                    minOf(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1
                }
            }
        }
        return dp[a.length][b.length]
    }
}

data class MatchResult(val manga: MangaDto, val similarity: Double)
