```kotlin
// Illustrative: migration flow orchestration
class MigrationManager @Inject constructor(
    private val sourceManager: SourceManager,
    private val titleMatcher: TitleMatcher,
    private val libraryDao: LibraryDao,
    private val migrationRepository: MigrationRepository
) {
    suspend fun scanForDeadSources(): List<DeadSourceReport> {
        val sourcesInLibrary = libraryDao.getAllSources()
        return sourcesInLibrary.mapNotNull { sourceId ->
            val source = sourceManager.getSource(sourceId) ?: return@mapNotNull null
            val healthCheck = runCatching { source.fetchPopularManga(1) }
            if (healthCheck.isFailure) {
                DeadSourceReport(
                    sourceId = sourceId,
                    sourceName = source.name,
                    affectedMangaCount = libraryDao.countBySource(sourceId),
                    lastError = healthCheck.exceptionOrNull()?.message
                )
            } else null
        }
    }

    suspend fun findAlternatives(
        manga: LibraryManga,
        targetSources: List<ShinKuSource>
    ): List<MigrationCandidate> {
        val normalizedTitle = manga.title

        return targetSources.flatMap { source ->
            runCatching {
                source.fetchSearchResults(normalizedTitle, 1)
            }.getOrElse { emptyList() }
        }.let { candidates ->
            titleMatcher.findMatches(manga.title, candidates)
                .map { match ->
                    MigrationCandidate(
                        originalManga = manga,
                        newManga = match.manga,
                        newSourceId = match.manga.sourceId,
                        confidence = match.similarity
                    )
                }
        }
    }

    suspend fun executeMigration(
        candidate: MigrationCandidate,
        onProgress: (Int, Int) -> Unit
    ): Result<Unit> = runCatching {
        libraryDao.runInTransaction {
            // 1. Add new title
            val newId = libraryDao.insert(candidate.toNewEntity())
            // 2. Transfer metadata
            libraryDao.transferMetadata(
                fromId = candidate.originalManga.id,
                toId = newId
            )
            // 3. Remove old title
            libraryDao.delete(candidate.originalManga.id)
        }
    }
}
```

