🛠️ IMPLEMENTATION DETAILS

3.1 Current State

Kototoro already has:

· A dynamic plugin system that loads .jar (Dex) files at runtime via PluginClassLoader
· A GlobalExtensionManager that aggregates sources from JarExtensionLoader and ApkExtensionLoader
· An Import Plugin (.jar) button in Settings > Remote Sources > Installed Plugins
· Support for configuring compatible extension repositories for in-app browsing and installation
· A GitHub Actions pipeline for building and publishing parser JARs

3.2 Proposed Addition

Add a "Plugin Repository" section where users can:

1. Add a repository URL (pre-populated with https://github.com/Shebyyy/kotatsu-multi-parsers)
2. Browse available JARs from the repository's latest release
3. Install any JAR with one tap — the app downloads the JAR and loads it via PluginClassLoader

3.3 Technical Architecture

The integration follows the same pattern as existing repository integrations:

```
[User opens Settings → Content Sources → Extensions → Plugins]
                    ↓
[User taps "Add Repository" — URL pre-filled]
                    ↓
[App fetches https://api.github.com/repos/Shebyyy/kotatsu-multi-parsers/releases/latest]
                    ↓
[App parses the release assets and displays available JARs]
                    ↓
[User taps "Install" on any JAR (e.g., "YakaTeam.jar")]
                    ↓
[App downloads the JAR to files/plugins/ directory]
                    ↓
[GlobalExtensionManager.initialize(context) is triggered]
                    ↓
[Plugin is immediately available — UI reacts seamlessly via MutableStateFlow][reference:16]
```

3.4 Refined Code Implementation

```kotlin
// PluginRepositoryManager.kt — Manages plugin repositories and installation

package org.koitharu.kototoro.core.plugin

import android.content.Context
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.withContext
import org.koitharu.kototoro.core.manager.GlobalExtensionManager
import java.io.File
import java.net.URL

/**
 * Manages plugin repositories and provides one-tap installation of parser JARs.
 * Follows the same pattern as existing Mihon/Aniyomi extension repositories.
 * 
 * @see GlobalExtensionManager
 * @see [Dynamic Plugin System Architecture]
 */
class PluginRepositoryManager(
    private val context: Context,
    private val extensionManager: GlobalExtensionManager
) {
    private val _state = MutableStateFlow<RepositoryState>(RepositoryState.Idle)
    val state: StateFlow<RepositoryState> = _state

    companion object {
        /**
         * Default plugin repositories pre-configured for users.
         * Users can add additional repositories manually.
         */
        val DEFAULT_REPOSITORIES = listOf(
            PluginRepository(
                id = "kotatsu-multi-parsers",
                name = "Kotatsu Multi-Parsers",
                url = "https://github.com/Shebyyy/kotatsu-multi-parsers",
                description = "Collection of parsers from multiple Kotatsu-based repositories",
                maintainer = "Shebyyy",
                isOfficial = true
            )
        )
    }

    /**
     * Fetches available plugin JARs from a repository's latest GitHub Release.
     * Uses the GitHub API to get release assets.
     */
    suspend fun fetchAvailablePlugins(repo: PluginRepository): Result<List<PluginAsset>> =
        withContext(Dispatchers.IO) {
            try {
                _state.value = RepositoryState.Loading(repo.id)

                // GitHub API endpoint for the latest release
                val apiUrl = "${repo.url}/releases/latest"
                val connection = URL(apiUrl).openConnection()
                connection.setRequestProperty("Accept", "application/vnd.github.v3+json")

                val response = connection.getInputStream().bufferedReader().readText()
                val release = json.decodeFromString<GitHubRelease>(response)

                val assets = release.assets
                    .filter { it.name.endsWith(".jar") }
                    .map { asset ->
                        PluginAsset(
                            name = asset.name,
                            downloadUrl = asset.browser_download_url,
                            size = asset.size,
                            contentType = asset.content_type,
                            createdAt = asset.created_at
                        )
                    }

                _state.value = RepositoryState.Loaded(repo.id, assets)
                Result.success(assets)
            } catch (e: Exception) {
                _state.value = RepositoryState.Error(repo.id, e.message ?: "Unknown error")
                Result.failure(e)
            }
        }

    /**
     * Downloads and installs a plugin JAR.
     * The app copies the JAR to its private files/plugins/ directory and triggers
     * GlobalExtensionManager.initialize(context)[reference:17].
     */
    suspend fun installPlugin(asset: PluginAsset): Result<Unit> =
        withContext(Dispatchers.IO) {
            try {
                _state.value = RepositoryState.Installing(asset.name)

                // Download the JAR
                val jarBytes = URL(asset.downloadUrl).readBytes()

                // Save to plugins directory
                val pluginsDir = File(context.filesDir, "plugins")
                if (!pluginsDir.exists()) {
                    pluginsDir.mkdirs()
                }

                val jarFile = File(pluginsDir, asset.name)
                jarFile.writeBytes(jarBytes)

                // Trigger extension reload — this makes the plugin immediately available[reference:18]
                extensionManager.initialize(context)

                _state.value = RepositoryState.Installed(asset.name)
                Result.success(Unit)
            } catch (e: Exception) {
                _state.value = RepositoryState.Error(asset.name, e.message ?: "Installation failed")
                Result.failure(e)
            }
        }

    /**
     * Removes an installed plugin JAR.
     */
    suspend fun uninstallPlugin(pluginName: String): Result<Unit> =
        withContext(Dispatchers.IO) {
            try {
                val jarFile = File(context.filesDir, "plugins/$pluginName")
                if (jarFile.exists()) {
                    jarFile.delete()
                }
                extensionManager.initialize(context)
                Result.success(Unit)
            } catch (e: Exception) {
                Result.failure(e)
            }
        }
}

/**
 * Represents a plugin repository.
 */
data class PluginRepository(
    val id: String,
    val name: String,
    val url: String,
    val description: String,
    val maintainer: String,
    val isOfficial: Boolean = false
)

/**
 * Represents a plugin asset from a GitHub Release.
 */
data class PluginAsset(
    val name: String,
    val downloadUrl: String,
    val size: Long,
    val contentType: String,
    val createdAt: String
)

/**
 * GitHub API response model for a release.
 */
@Serializable
data class GitHubRelease(
    val tag_name: String,
    val name: String,
    val body: String,
    val published_at: String,
    val assets: List<GitHubAsset>
)

@Serializable
data class GitHubAsset(
    val name: String,
    val browser_download_url: String,
    val size: Long,
    val content_type: String,
    val created_at: String
)

/**
 * Repository state for UI updates.
 */
sealed class RepositoryState {
    data object Idle : RepositoryState()
    data class Loading(val repositoryId: String) : RepositoryState()
    data class Loaded(val repositoryId: String, val assets: List<PluginAsset>) : RepositoryState()
    data class Installing(val pluginName: String) : RepositoryState()
    data class Installed(val pluginName: String) : RepositoryState()
    data class Error(val context: String, val message: String) : RepositoryState()
}
