// PluginRepositoryScreen.kt — UI for browsing and installing plugins

@Composable
fun PluginRepositoryScreen(
    viewModel: PluginRepositoryViewModel = hiltViewModel()
) {
    val state by viewModel.state.collectAsState()
    val repositories = viewModel.repositories.collectAsState()

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Plugin Repositories") },
                actions = {
                    IconButton(onClick = { viewModel.addRepository() }) {
                        Icon(Icons.Default.Add, contentDescription = "Add Repository")
                    }
                }
            )
        }
    ) { paddingValues ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
        ) {
            // Default repositories section
            item {
                Text(
                    text = "Official Repositories",
                    style = MaterialTheme.typography.titleMedium,
                    modifier = Modifier.padding(16.dp)
                )
            }

            items(repositories.value.filter { it.isOfficial }) { repo ->
                RepositoryCard(
                    repository = repo,
                    state = state,
                    onFetch = { viewModel.fetchPlugins(repo) },
                    onInstall = { asset -> viewModel.installPlugin(asset) }
                )
            }

            // User-added repositories section
            if (repositories.value.any { !it.isOfficial }) {
                item {
                    Text(
                        text = "Custom Repositories",
                        style = MaterialTheme.typography.titleMedium,
                        modifier = Modifier.padding(16.dp)
                    )
                }

                items(repositories.value.filter { !it.isOfficial }) { repo ->
                    RepositoryCard(
                        repository = repo,
                        state = state,
                        onFetch = { viewModel.fetchPlugins(repo) },
                        onInstall = { asset -> viewModel.installPlugin(asset) },
                        onRemove = { viewModel.removeRepository(repo) }
                    )
                }
            }
        }
    }
}

@Composable
fun RepositoryCard(
    repository: PluginRepository,
    state: RepositoryState,
    onFetch: () -> Unit,
    onInstall: (PluginAsset) -> Unit,
    onRemove: (() -> Unit)? = null
) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 8.dp)
    ) {
        Column(
            modifier = Modifier.padding(16.dp)
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Column {
                    Text(
                        text = repository.name,
                        style = MaterialTheme.typography.titleMedium
                    )
                    Text(
                        text = repository.description,
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                    Text(
                        text = "Maintainer: ${repository.maintainer}",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
                if (onRemove != null) {
                    IconButton(onClick = onRemove) {
                        Icon(Icons.Default.Close, contentDescription = "Remove")
                    }
                }
            }

            Spacer(modifier = Modifier.height(8.dp))

            // Fetch button
            Button(
                onClick = onFetch,
                enabled = state !is RepositoryState.Loading
            ) {
                if (state is RepositoryState.Loading && state.repositoryId == repository.id) {
                    CircularProgressIndicator(
                        modifier = Modifier.size(20.dp),
                        color = MaterialTheme.colorScheme.onPrimary
                    )
                } else {
                    Text("Browse Plugins")
                }
            }

            // Show available plugins if loaded
            if (state is RepositoryState.Loaded && state.repositoryId == repository.id) {
                Spacer(modifier = Modifier.height(8.dp))
                Text(
                    text = "${state.assets.size} plugins available",
                    style = MaterialTheme.typography.bodySmall
                )

                state.assets.forEach { asset ->
                    PluginItem(
                        asset = asset,
                        onInstall = { onInstall(asset) },
                        isInstalling = state is RepositoryState.Installing && 
                                      state.pluginName == asset.name
                    )
                }
            }

            // Show error if any
            if (state is RepositoryState.Error && state.context == repository.id) {
                Spacer(modifier = Modifier.height(8.dp))
                Text(
                    text = "Error: ${state.message}",
                    color = MaterialTheme.colorScheme.error,
                    style = MaterialTheme.typography.bodySmall
                )
            }
        }
    }
}

@Composable
fun PluginItem(
    asset: PluginAsset,
    onInstall: () -> Unit,
    isInstalling: Boolean
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 4.dp),
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Column {
            Text(
                text = asset.name,
                style = MaterialTheme.typography.bodyMedium
            )
            Text(
                text = "Size: ${asset.size / 1024} KB",
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
        }

        Button(
            onClick = onInstall,
            enabled = !isInstalling,
            modifier = Modifier
        ) {
            if (isInstalling) {
                CircularProgressIndicator(
                    modifier = Modifier.size(16.dp),
                    color = MaterialTheme.colorScheme.onPrimary
                )
            } else {
                Text("Install")
            }
        }
    }
}
