@HiltViewModel
class PluginRepositoryViewModel @Inject constructor(
    private val repositoryManager: PluginRepositoryManager,
    private val settingsRepository: SettingsRepository
) : ViewModel() {

    private val _repositories = MutableStateFlow(
        PluginRepositoryManager.DEFAULT_REPOSITORIES
    )
    val repositories: StateFlow<List<PluginRepository>> = _repositories

    private val _state = MutableStateFlow<RepositoryState>(RepositoryState.Idle)
    val state: StateFlow<RepositoryState> = _state

    fun fetchPlugins(repo: PluginRepository) {
        viewModelScope.launch {
            repositoryManager.fetchAvailablePlugins(repo).fold(
                onSuccess = { assets ->
                    _state.value = RepositoryState.Loaded(repo.id, assets)
                },
                onFailure = { error ->
                    _state.value = RepositoryState.Error(repo.id, error.message ?: "Unknown error")
                }
            )
        }
    }

    fun installPlugin(asset: PluginAsset) {
        viewModelScope.launch {
            repositoryManager.installPlugin(asset).fold(
                onSuccess = {
                    // Plugin installed — UI will update via GlobalExtensionManager
                },
                onFailure = { error ->
                    _state.value = RepositoryState.Error(asset.name, error.message ?: "Installation failed")
                }
            )
        }
    }

    fun addRepository() {
        // Show dialog for user to enter repository URL
        // Validate and add to _repositories
    }

    fun removeRepository(repo: PluginRepository) {
        _repositories.value = _repositories.value.filter { it.id != repo.id }
        settingsRepository.removePluginRepository(repo.id)
    }
}
